<script lang="ts">
 import {onMount} from 'svelte';
 import {request} from './api';
 import {Input} from '$lib/components/ui/input';
 import {Textarea} from '$lib/components/ui/textarea';
 import {Button} from '$lib/components/ui/button';
 import {LoaderCircle,Plus,Trash2,ExternalLink} from '@lucide/svelte';
 let {onSaved=()=>{}}:{onSaved?:(user:any)=>void}=$props();
 let profile=$state<any>(null),loading=$state(true),busy=$state(false),error=$state(''),notice=$state('');
 async function load(){loading=true;error='';try{const result=await request('/profile');profile={...result.channel,social_links:result.channel.social_links || []};}catch(e){error=(e as Error).message;}finally{loading=false;}}
 onMount(()=>{void load();});
 async function save(){busy=true;error='';notice='';try{const {name,bio,location,avatar_url,banner_url,website,social_links,featured_video_id}=profile;const result=await request('/profile',{name,bio,location,avatar_url,banner_url,website,social_links,featured_video_id},'PATCH');profile={...result.channel,social_links:result.channel.social_links || []};onSaved(result.user);notice='Your public profile has been updated.';}catch(e){error=(e as Error).message;}finally{busy=false;}}
</script>
<div class="page-heading"><h1>Edit public profile</h1><p>Your profile is shared by your viewing account and creator channel. Email and security settings stay private.</p></div>
{#if error}<div class="cloud-alert" role="alert">{error}{#if !profile}<Button variant="outline" onclick={load}>Retry</Button>{/if}</div>{/if}{#if notice}<p class="cloud-notice" role="status">{notice}</p>{/if}
{#if loading}<div class="cloud-loading" role="status"><LoaderCircle class="size-5 animate-spin"/>Loading profile…</div>{:else if profile}<form class="cloud-panel profile-editor" onsubmit={(event)=>{event.preventDefault();void save();}}><div class="section-heading"><h2>Public identity</h2><a href={`/channels/${profile.handle}`} class="inline-flex items-center gap-1 text-sm underline underline-offset-4">View profile<ExternalLink class="size-3.5"/></a></div><label for="profile-name">Display name</label><Input id="profile-name" bind:value={profile.name} required maxlength={100} autocomplete="name"/><label for="profile-bio">Bio</label><Textarea id="profile-bio" bind:value={profile.bio} rows={4} maxlength={2000}/><label for="profile-location">Location <span class="subtle">(optional)</span></label><Input id="profile-location" bind:value={profile.location} maxlength={120}/><div class="form-grid"><div><label for="profile-avatar">Avatar image URL</label><Input id="profile-avatar" type="url" pattern="https://.*" bind:value={profile.avatar_url} placeholder="https://"/></div><div><label for="profile-banner">Banner image URL</label><Input id="profile-banner" type="url" pattern="https://.*" bind:value={profile.banner_url} placeholder="https://"/></div></div><p class="field-help">Use HTTPS image links. SVG and data URLs are not accepted. Leave a URL empty to remove it.</p><label for="profile-website">Website</label><Input id="profile-website" type="url" pattern="https://.*" bind:value={profile.website} placeholder="https://"/><div class="section-heading profile-links-heading"><h2>Social links</h2><Button type="button" variant="outline" size="sm" disabled={profile.social_links.length>=8} onclick={()=>profile.social_links=[...profile.social_links,{label:'',url:''}]}><Plus class="size-4"/>Add link</Button></div>{#each profile.social_links as link,index}<div class="profile-link-row"><div><label for={`social-label-${index}`}>Label {index+1}</label><Input id={`social-label-${index}`} bind:value={link.label} required maxlength={40}/></div><div><label for={`social-url-${index}`}>HTTPS URL</label><Input id={`social-url-${index}`} type="url" pattern="https://.*" bind:value={link.url} required/></div><Button type="button" variant="ghost" size="icon" aria-label={`Remove social link ${index+1}`} onclick={()=>profile.social_links=profile.social_links.filter((_:unknown,i:number)=>i!==index)}><Trash2 class="size-4"/></Button></div>{/each}<div class="profile-save"><p class="field-help">Only information you enter here appears on your public profile.</p><Button type="submit" disabled={busy}>{#if busy}<LoaderCircle class="size-4 animate-spin"/>{/if}Save profile</Button></div></form>{/if}
